import React, { useState, useEffect, useMemo } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import { useCollection } from '../../hooks/useCollection';
import { useFirestore } from '../../hooks/useFirestore';
import {
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import './admindashboard.css';

// Couleurs du design system
const COLORS = {
  primary: '#8d69f1',
  secondary: '#667eea',
  success: '#22c55e',
  warning: '#f59e0b',
  error: '#ef4444',
  dark: '#1f2937',
  light: '#f8fafc'
};

const AdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [dateRange, setDateRange] = useState('month');

  // Données Firestore
  const { documents: users } = useCollection('users');
  const { documents: courses } = useCollection('courses');
  const { documents: payments } = useCollection('payments');
  const { documents: enrollments } = useCollection('enrollments');
  const { updateDocument: updateCourse, deleteDocument: deleteCourse } = useFirestore('courses');
  const { updateDocument: updateUser } = useFirestore('users');

  // Métriques calculées
  const dashboardStats = useMemo(() => {
    if (!users || !courses || !payments) return null;

    const completedPayments = payments.filter(p => p.status === 'completed');
    const totalRevenue = completedPayments.reduce((sum, p) => sum + (p.amount || 0), 0);
    
    // Revenu mensuel
    const currentMonth = new Date().getMonth();
    const monthlyRevenue = completedPayments
      .filter(p => {
        const paymentDate = p.createdAt?.toDate();
        return paymentDate && paymentDate.getMonth() === currentMonth;
      })
      .reduce((sum, p) => sum + (p.amount || 0), 0);

    // Cours populaires
    const popularCourses = courses
      .map(course => {
        const courseEnrollments = enrollments?.filter(e => e.courseId === course.id).length || 0;
        return {
          ...course,
          enrollmentCount: courseEnrollments,
          revenue: (course.price || 0) * courseEnrollments
        };
      })
      .sort((a, b) => b.enrollmentCount - a.enrollmentCount)
      .slice(0, 5);

    // Données pour graphiques
    const revenueData = generateRevenueData(payments);
    const categoryData = generateCategoryData(courses, enrollments);
    const userGrowthData = generateUserGrowthData(users);

    return {
      totalRevenue,
      monthlyRevenue,
      totalStudents: users.filter(u => u.role === 'student').length,
      totalCourses: courses.length,
      totalInstructors: users.filter(u => u.role === 'instructor').length,
      activeUsers: users.filter(u => u.online).length,
      conversionRate: calculateConversionRate(users, payments),
      popularCourses,
      revenueData,
      categoryData,
      userGrowthData,
      monthlyGrowth: calculateMonthlyGrowth(payments)
    };
  }, [users, courses, payments, enrollments]);

  // Fonctions utilitaires
  const generateRevenueData = (payments) => {
    const months = ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Jun', 'Jul', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'];
    return months.map((month, index) => ({
      month,
      revenue: payments
        .filter(p => p.status === 'completed' && p.createdAt?.toDate().getMonth() === index)
        .reduce((sum, p) => sum + (p.amount || 0), 0)
    }));
  };

  const generateCategoryData = (courses, enrollments) => {
    const categories = [...new Set(courses.map(c => c.category))];
    return categories.map(category => {
      const categoryCourses = courses.filter(c => c.category === category);
      const students = categoryCourses.reduce((sum, course) => {
        const courseEnrollments = enrollments?.filter(e => e.courseId === course.id).length || 0;
        return sum + courseEnrollments;
      }, 0);
      return { name: category, value: students };
    });
  };

  const generateUserGrowthData = (users) => {
    const months = ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Jun'];
    return months.map((month, index) => ({
      month,
      users: users.filter(u => {
        const userDate = u.createdAt?.toDate();
        return userDate && userDate.getMonth() === index;
      }).length
    }));
  };

  const calculateConversionRate = (users, payments) => {
    const totalUsers = users.filter(u => u.role === 'student').length;
    const payingUsers = [...new Set(payments.filter(p => p.status === 'completed').map(p => p.userId))].length;
    return totalUsers > 0 ? (payingUsers / totalUsers * 100).toFixed(1) : 0;
  };

  const calculateMonthlyGrowth = (payments) => {
    const currentMonth = new Date().getMonth();
    const previousMonth = currentMonth === 0 ? 11 : currentMonth - 1;
    
    const currentRevenue = payments
      .filter(p => p.status === 'completed' && p.createdAt?.toDate().getMonth() === currentMonth)
      .reduce((sum, p) => sum + (p.amount || 0), 0);
    
    const previousRevenue = payments
      .filter(p => p.status === 'completed' && p.createdAt?.toDate().getMonth() === previousMonth)
      .reduce((sum, p) => sum + (p.amount || 0), 0);

    return previousRevenue > 0 ? ((currentRevenue - previousRevenue) / previousRevenue * 100).toFixed(1) : 100;
  };

  // Gestion des cours
  const handleCourseStatusUpdate = async (courseId, newStatus) => {
    try {
      await updateCourse(courseId, { status: newStatus });
    } catch (error) {
      console.error('Erreur mise à jour cours:', error);
    }
  };

  const handleUserStatusUpdate = async (userId, updates) => {
    try {
      await updateUser(userId, updates);
    } catch (error) {
      console.error('Erreur mise à jour utilisateur:', error);
    }
  };

  // Filtrage des données
  const filteredCourses = useMemo(() => {
    if (!courses) return [];
    return courses.filter(course => {
      const matchesSearch = course.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           course.instructor?.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = selectedCategory === 'all' || course.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [courses, searchTerm, selectedCategory]);

  const filteredUsers = useMemo(() => {
    if (!users) return [];
    return users.filter(user => {
      return user.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
             user.email.toLowerCase().includes(searchTerm.toLowerCase());
    });
  }, [users, searchTerm]);

  useEffect(() => {
    if (users && courses && payments) {
      setLoading(false);
    }
  }, [users, courses, payments]);

  if (!isAdmin) {
    return (
      <div className="admin-dashboard">
        <div className="access-denied">
          <h2>🚫 Accès Refusé</h2>
          <p>Vous n'avez pas les permissions nécessaires pour accéder à cette page.</p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="admin-dashboard">
        <div className="loading-state">
          <div className="loading-spinner"></div>
          <p>Chargement des données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard">
      <div className="admin-layout">
        {/* Navigation Sidebar */}
        <nav className="admin-sidebar">
          <div className="sidebar-header">
            <h2>🎓 EduPlatform</h2>
            <p>Dashboard Admin</p>
          </div>
          
          <div className="sidebar-nav">
            {[
              { id: 'overview', label: 'Vue d\'ensemble', icon: '📊' },
              { id: 'courses', label: 'Gestion des Cours', icon: '📚' },
              { id: 'users', label: 'Gestion Utilisateurs', icon: '👥' },
              { id: 'payments', label: 'Paiements', icon: '💳' },
              { id: 'analytics', label: 'Analytiques', icon: '📈' },
              { id: 'settings', label: 'Paramètres', icon: '⚙️' }
            ].map(tab => (
              <button
                key={tab.id}
                className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}
                onClick={() => setActiveTab(tab.id)}
              >
                <span className="nav-icon">{tab.icon}</span>
                <span className="nav-label">{tab.label}</span>
              </button>
            ))}
          </div>
        </nav>

        {/* Contenu Principal */}
        <main className="admin-main">
          <header className="admin-header">
            <div className="header-title">
              <h1>
                {activeTab === 'overview' && 'Vue d\'Ensemble'}
                {activeTab === 'courses' && 'Gestion des Cours'}
                {activeTab === 'users' && 'Gestion des Utilisateurs'}
                {activeTab === 'payments' && 'Gestion des Paiements'}
                {activeTab === 'analytics' && 'Analytiques Avancées'}
                {activeTab === 'settings' && 'Paramètres Système'}
              </h1>
              <p>Bienvenue, {user?.displayName || 'Administrateur'} 👋</p>
            </div>
            
            <div className="header-actions">
              <div className="date-filter">
                <select 
                  value={dateRange} 
                  onChange={(e) => setDateRange(e.target.value)}
                  className="filter-select"
                >
                  <option value="week">7 derniers jours</option>
                  <option value="month">30 derniers jours</option>
                  <option value="quarter">3 derniers mois</option>
                  <option value="year">Cette année</option>
                </select>
              </div>
            </div>
          </header>

          <div className="admin-content">
            {/* Vue d'ensemble */}
            {activeTab === 'overview' && dashboardStats && (
              <div className="overview-tab">
                <div className="stats-grid">
                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon" style={{ background: 'rgba(139, 92, 246, 0.1)', color: COLORS.primary }}>💰</div>
                      <div className="stat-trend positive">+{dashboardStats.monthlyGrowth}%</div>
                    </div>
                    <div className="stat-value">{dashboardStats.totalRevenue.toLocaleString()} TND</div>
                    <div className="stat-label">Revenus Totaux</div>
                    <div className="stat-subtitle">{dashboardStats.monthlyRevenue.toLocaleString()} TND ce mois</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon" style={{ background: 'rgba(34, 197, 94, 0.1)', color: COLORS.success }}>👥</div>
                      <div className="stat-trend positive">+12%</div>
                    </div>
                    <div className="stat-value">{dashboardStats.totalStudents}</div>
                    <div className="stat-label">Étudiants Actifs</div>
                    <div className="stat-subtitle">{dashboardStats.activeUsers} en ligne</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon" style={{ background: 'rgba(245, 158, 11, 0.1)', color: COLORS.warning }}>📚</div>
                      <div className="stat-trend positive">+5%</div>
                    </div>
                    <div className="stat-value">{dashboardStats.totalCourses}</div>
                    <div className="stat-label">Cours Disponibles</div>
                    <div className="stat-subtitle">{dashboardStats.totalInstructors} formateurs</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon" style={{ background: 'rgba(239, 68, 68, 0.1)', color: COLORS.error }}>📈</div>
                      <div className="stat-trend positive">+8%</div>
                    </div>
                    <div className="stat-value">{dashboardStats.conversionRate}%</div>
                    <div className="stat-label">Taux de Conversion</div>
                    <div className="stat-subtitle">Performance moyenne</div>
                  </div>
                </div>

                {/* Graphiques Principaux */}
                <div className="charts-grid">
                  <div className="chart-card">
                    <h3>Revenus Mensuels</h3>
                    <ResponsiveContainer width="100%" height={300}>
                      <LineChart data={dashboardStats.revenueData}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="month" />
                        <YAxis />
                        <Tooltip formatter={(value) => [`${value} TND`, 'Revenu']} />
                        <Legend />
                        <Line 
                          type="monotone" 
                          dataKey="revenue" 
                          stroke={COLORS.primary}
                          strokeWidth={3}
                          dot={{ fill: COLORS.primary }}
                        />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>

                  <div className="chart-card">
                    <h3>Répartition par Catégorie</h3>
                    <ResponsiveContainer width="100%" height={300}>
                      <PieChart>
                        <Pie
                          data={dashboardStats.categoryData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
                          outerRadius={80}
                          fill="#8884d8"
                          dataKey="value"
                        >
                          {dashboardStats.categoryData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={Object.values(COLORS)[index % 6]} />
                          ))}
                        </Pie>
                        <Tooltip formatter={(value) => [`${value} étudiants`, 'Nombre']} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                {/* Cours Populaires */}
                <div className="popular-courses">
                  <h3>Cours les Plus Populaires</h3>
                  <div className="courses-list">
                    {dashboardStats.popularCourses.map((course, index) => (
                      <div key={course.id} className="popular-course-item">
                        <span className="rank">#{index + 1}</span>
                        <img src={course.image} alt={course.title} className="course-image" />
                        <div className="course-info">
                          <h4>{course.title}</h4>
                          <p>{course.category} • {course.instructor?.name}</p>
                        </div>
                        <div className="course-stats">
                          <span className="students">👥 {course.enrollmentCount}</span>
                          <span className="revenue">💰 {course.revenue} TND</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Gestion des Cours */}
            {activeTab === 'courses' && (
              <div className="courses-tab">
                <div className="tab-header">
                  <h2>Gestion des Cours</h2>
                  <button className="btn btn-primary">+ Nouveau Cours</button>
                </div>

                <div className="filters-bar">
                  <div className="search-box">
                    <input
                      type="text"
                      placeholder="Rechercher un cours..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="search-input"
                    />
                  </div>
                  <select 
                    value={selectedCategory} 
                    onChange={(e) => setSelectedCategory(e.target.value)}
                    className="filter-select"
                  >
                    <option value="all">Toutes les catégories</option>
                    <option value="Développement">Développement</option>
                    <option value="Design">Design</option>
                    <option value="Business">Business</option>
                  </select>
                </div>

                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Cours</th>
                        <th>Catégorie</th>
                        <th>Formateur</th>
                        <th>Prix</th>
                        <th>Étudiants</th>
                        <th>Statut</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredCourses.map(course => (
                        <tr key={course.id}>
                          <td>
                            <div className="course-cell">
                              <img src={course.image} alt={course.title} className="course-thumb" />
                              <div>
                                <strong>{course.title}</strong>
                                <p className="course-description">{course.description?.substring(0, 50)}...</p>
                              </div>
                            </div>
                          </td>
                          <td>{course.category}</td>
                          <td>{course.instructor?.name}</td>
                          <td>{course.price} TND</td>
                          <td>{course.students || 0}</td>
                          <td>
                            <select 
                              value={course.status || 'draft'} 
                              onChange={(e) => handleCourseStatusUpdate(course.id, e.target.value)}
                              className={`status-select ${course.status}`}
                            >
                              <option value="draft">Brouillon</option>
                              <option value="published">Publié</option>
                              <option value="archived">Archivé</option>
                            </select>
                          </td>
                          <td>
                            <div className="action-buttons">
                              <button className="btn-icon" title="Éditer">✏️</button>
                              <button 
                                className="btn-icon btn-danger" 
                                title="Supprimer"
                                onClick={() => {
                                  if (window.confirm('Supprimer ce cours ?')) {
                                    deleteCourse(course.id);
                                  }
                                }}
                              >
                                🗑️
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Gestion des Utilisateurs */}
            {activeTab === 'users' && (
              <div className="users-tab">
                <div className="tab-header">
                  <h2>Gestion des Utilisateurs</h2>
                </div>

                <div className="filters-bar">
                  <div className="search-box">
                    <input
                      type="text"
                      placeholder="Rechercher un utilisateur..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="search-input"
                    />
                  </div>
                </div>

                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Utilisateur</th>
                        <th>Email</th>
                        <th>Rôle</th>
                        <th>Inscription</th>
                        <th>Statut</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredUsers.map(user => (
                        <tr key={user.id}>
                          <td>
                            <div className="user-cell">
                              <div className="user-avatar">
                                {user.photoURL ? (
                                  <img src={user.photoURL} alt={user.displayName} />
                                ) : (
                                  <div className="avatar-placeholder">
                                    {user.displayName?.charAt(0) || user.email.charAt(0)}
                                  </div>
                                )}
                              </div>
                              <div>
                                <strong>{user.displayName || 'Utilisateur'}</strong>
                                <p className="user-meta">
                                  {user.lastLogin && `Dernière connexion: ${user.lastLogin.toDate().toLocaleDateString()}`}
                                </p>
                              </div>
                            </div>
                          </td>
                          <td>{user.email}</td>
                          <td>
                            <span className={`badge badge-${user.role}`}>
                              {user.role === 'admin' ? 'Administrateur' : 
                               user.role === 'instructor' ? 'Formateur' : 'Étudiant'}
                            </span>
                          </td>
                          <td>{user.createdAt?.toDate().toLocaleDateString()}</td>
                          <td>
                            <div className="status-cell">
                              <span className={`badge ${user.online ? 'badge-success' : 'badge-warning'}`}>
                                {user.online ? 'En ligne' : 'Hors ligne'}
                              </span>
                              <span className={`badge ${user.active !== false ? 'badge-success' : 'badge-danger'}`}>
                                {user.active !== false ? 'Actif' : 'Inactif'}
                              </span>
                            </div>
                          </td>
                          <td>
                            <div className="action-buttons">
                              <button className="btn-icon" title="Voir profil">👁️</button>
                              <button 
                                className="btn-icon btn-warning" 
                                title={user.active !== false ? 'Désactiver' : 'Activer'}
                                onClick={() => handleUserStatusUpdate(user.id, { active: !user.active })}
                              >
                                {user.active !== false ? '🚫' : '✅'}
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Autres onglets... */}
            {activeTab === 'payments' && (
              <div className="payments-tab">
                <h2>Gestion des Paiements</h2>
                <p>Interface d'intégration Paymee en cours de développement...</p>
              </div>
            )}

            {activeTab === 'analytics' && (
              <div className="analytics-tab">
                <h2>Analytiques Avancées</h2>
                {/* Graphiques supplémentaires */}
              </div>
            )}

            {activeTab === 'settings' && (
              <div className="settings-tab">
                <h2>Paramètres Système</h2>
                {/* Configuration Paymee et autres paramètres */}
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;
